minimal_patch:
在 scripts/lib/daily-task-board.mjs 中新增 writeUnknownFailureEvidence 函数，并在 syncDailyBoard 的 recoverArtifact 返回 false 且 seat.status === 'generation_unknown_no_repurchase' 时调用该函数，将状态改为 generation_failed_no_repurchase 后继续走 syncFailedSeat 路径。补丁如下：

function writeUnknownFailureEvidence(root, record, agent, seat) {
  if (seat.artifact || !seat.assignment || !seat.claim_verified) return false;
  const body = {
    schema_version: 1,
    date: record.date,
    run_key: record.run_key,
    task_id: seat.assignment.id,
    logical_seat: agent,
    actual_provider: null,
    actual_model: null,
    reported_model: null,
    model_source: null,
    source_commit: record.source_commit,
    output: '',
    finish_reason: null,
    tokens_used: null,
    request_id: null,
    integrity: {status:'missing_required_section', reason:'provider_result_unknown'},
    required_sections: requiredSectionsForAgent(agent),
    status: 'incomplete_or_failed',
    provider_status: null,
    accepted: false,
    paid: false,
    tx_hash: null
  };
  const bytes = JSON.stringify(body, null, 2) + '\n';
  const hash = digest(bytes);
  const relative = `knowledge/results/daily-board/artifacts/${record.date}-${agent}-${hash}.json`;
  const file = path.join(root, relative);
  try {
    fs.mkdirSync(path.dirname(file), {recursive: true});
    fs.writeFileSync(file, bytes, {flag:'wx'});
  } catch {
    return false;
  }
  seat.artifact = {path: relative, sha256: hash};
  seat.status = 'generation_failed_no_repurchase';
  seat.integrity = body.integrity;
  seat.recovery = 'unknown_failure_evidence_written_no_model_replay';
  saveLedger(root, record);
  return true;
}

在 syncDailyBoard 循环内 recoverArtifact(root,record,agent,seat) 之后、syncFailedSeat 判断之前插入：

if (seat.status === 'generation_unknown_no_repurchase' && !seat.artifact && seat.assignment && seat.claim_verified) {
  writeUnknownFailureEvidence(root, record, agent, seat);
}

再将 syncFailedSeat 触发条件中的状态列表改为包含 generation_unknown_no_repurchase，确保证据写入后必然进入 syncFailedSeat：

if(seat.assignment&&seat.claim_verified&&['missing_required_section','generation_failed_no_repurchase','generation_unknown_no_repurchase','failure_sync_unknown','failed_no_repurchase'].includes(seat.status)){await syncFailedSeat(...);continue;}
